    "viz_061": {
      "type": "splunk.column",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#16A3B0"
        ],
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "all"
      },
      "dataSources": {
        "primary": "ds_062"
      },
      "title": "Data sources needed per use case"
    },
    "bg_063": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_064": {
      "type": "splunk.pie",
      "options": {
        "backgroundColor": "#161B22",
        "showDonutHole": true,
        "labelDisplay": "valuesAndPercentage",
        "legendDisplay": "off",
        "seriesColors": [
          "#3987E5",
          "#D95926",
          "#199E70",
          "#C98500",
          "#D55181",
          "#008300",
          "#9085E9",
          "#E66767"
        ]
      },
      "dataSources": {
        "primary": "ds_065"
      },
      "title": "25 data sources by category"
    },
    "bg_066": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_067": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#161B22",
        "headerVisibility": "fixed",
        "fontSize": "small",
        "count": 25,
        "columnFormat": {
          "1 IP drift": {
            "rowColors": "> table | seriesByName(\"1 IP drift\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"1 IP drift\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "2 DB": {
            "rowColors": "> table | seriesByName(\"2 DB\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"2 DB\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "3 IoT": {
            "rowColors": "> table | seriesByName(\"3 IoT\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"3 IoT\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "4 Network": {
            "rowColors": "> table | seriesByName(\"4 Network\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"4 Network\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "5 Climate": {
            "rowColors": "> table | seriesByName(\"5 Climate\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"5 Climate\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "6 NSX": {
            "rowColors": "> table | seriesByName(\"6 NSX\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"6 NSX\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "7 Beds": {
            "rowColors": "> table | seriesByName(\"7 Beds\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"7 Beds\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "8 Cloud": {
            "rowColors": "> table | seriesByName(\"8 Cloud\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"8 Cloud\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "9 AI": {
            "rowColors": "> table | seriesByName(\"9 AI\") | matchValue(dot)",
            "rowBackgroundColors": "> table | seriesByName(\"9 AI\") | matchValue(dotBg)",
            "align": "center",
            "headerAlign": "center",
            "width": 96
          },
          "Data source": {
            "width": 300
          },
          "Category": {
            "width": 190,
            "rowColors": "> table | seriesByName(\"Category\") | matchValue(muted)"
          }
        }
      },
      "dataSources": {
        "primary": "ds_068"
      },
      "title": "Data sources needed in Splunk — and the use cases each one serves",
      "context": {
        "dot": [
          {
            "match": "✓",
            "value": "#5FE3EE"
          }
        ],
        "dotBg": [
          {
            "match": "✓",
            "value": "#12343A"
          }
        ],
        "muted": [
          {
            "match": "Applications",
            "value": "#9AA4B2"
          },
          {
            "match": "Clinical & facility",
            "value": "#9AA4B2"
          },
          {
            "match": "Cloud / security / AI",
            "value": "#9AA4B2"
          },
          {
            "match": "IT service management",
            "value": "#9AA4B2"
          },
          {
            "match": "Network",
            "value": "#9AA4B2"
          },
          {
            "match": "Servers & virtualization",
            "value": "#9AA4B2"
          }
        ]
      }
    }
  },
  "dataSources": {
    "ds_062": {
      "type": "ds.search",
      "name": "ds_062",
      "options": {
        "query": "| makeresults format=csv data=\"Use case,Data sources\n1 · IP drift,5\n2 · DB,4\n3 · IoT,4\n4 · Network,6\n5 · Climate,4\n6 · NSX,5\n7 · Beds,2\n8 · Cloud,5\n9 · AI,5\"\n| table \"Use case\" \"Data sources\"",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_065": {
      "type": "ds.search",
      "name": "ds_065",
      "options": {
        "query": "| makeresults format=csv data=\"Category,Sources\nNetwork,7\nServers & virtualization,5\nApplications,2\nClinical & facility,4\nIT service management,2\nCloud / security / AI,5\"\n| table Category Sources",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_068": {
      "type": "ds.search",
      "name": "ds_068",
      "options": {
        "query": "| makeresults format=csv data=\"Data source,Category,1 IP drift,2 DB,3 IoT,4 Network,5 Climate,6 NSX,7 Beds,8 Cloud,9 AI\nDHCP server logs,Network,✓,,,✓,,,,,\nSwitch & router syslog,Network,✓,,,✓,,,,,\nSNMP (interfaces & devices),Network,,,,✓,✓,,,,\nCisco ISE,Network,✓,,,✓,,,,,\nCatalyst Center (DNA) Assurance,Network,,,,✓,,,,,\nWireless LAN controller,Network,,,✓,✓,,,,,\nFirewall / proxy egress logs,Network,,,,,,,,✓,\nDatabase & cluster logs,Servers & virtualization,,✓,,,,,,,\nOS metrics (Windows / Linux),Servers & virtualization,,✓,,,,,,,\nStorage / SAN logs,Servers & virtualization,,✓,,,,,,,\nVMware NSX Manager (DFW),Servers & virtualization,,,,,,✓,,,\nVMware vCenter events,Servers & virtualization,,,,,,✓,,,\nApplication logs & health checks,Applications,,✓,,,,✓,,,✓\nPACS / DICOM gateway logs,Applications,✓,,,,,,,,\nIoT platform / gateway,Clinical & facility,,,✓,,✓,,,,\nBuilding management (BMS),Clinical & facility,,,,,✓,,,,\nHospital information system (ADT / HL7),Clinical & facility,,,,,,,✓,,\nBed management system,Clinical & facility,,,,,,,✓,,\nCMDB / asset inventory,IT service management,✓,,✓,,✓,✓,,,\nServiceNow tickets & changes,IT service management,,,✓,,,✓,,,\nCASB / secure web gateway,Cloud / security / AI,,,,,,,,✓,\nDLP / data classification,Cloud / security / AI,,,,,,,,✓,✓\nCloud audit logs (Azure / AWS / M365),Cloud / security / AI,,,,,,,,✓,✓\nIdentity (Entra ID / AD),Cloud / security / AI,,,,,,,,✓,✓\nAI gateway / LLM proxy logs,Cloud / security / AI,,,,,,,,,✓\"\n| table \"Data source\" Category \"1 IP drift\" \"2 DB\" \"3 IoT\" \"4 Network\" \"5 Climate\" \"6 NSX\" \"7 Beds\" \"8 Cloud\" \"9 AI\"",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [],
    "tabs": {
